window.__finlexDocLoaded(10022,{"id":10022,"articles":[{"id":1000047,"no":"Overview","heading":"Scope & Key Requirements (Public Summary)","text":"Deals with the auditor's responsibility to apply the concept of materiality in planning and performing an audit of financial statements, including performance materiality.","seq":0},{"id":1000048,"no":"ISA 320.10–14","heading":"Overall Materiality, Performance Materiality & Revisions","text":"• Overall materiality (ISA 320.10): determined for the financial statements as a whole using an appropriate benchmark (e.g., profit before tax, revenue, total assets).\n• Performance materiality (ISA 320.9, 11): set BELOW overall materiality to reduce to an appropriately low level the probability that aggregate uncorrected and undetected misstatements exceed overall materiality.\n• Revise materiality (ISA 320.12) if new information during the audit would have caused a different initial amount (converged with China CSA 1221).","seq":1},{"id":1000049,"no":"Official Access","heading":"Official Handbook & Reference Entry","text":"Official source (IAASB 2026 Handbook): https://www.iaasb.org/publications/2026-handbook-international-quality-management-auditing-review-sustainability-and-other-assurance\nStatus: in_force. Detailed paragraph-level summaries and practice notes can be expanded incrementally.\n2026 Handbook Volume: Volume 1 (ISQM 1–2, ISA 200–720)\nLocal Private Full-Text Import: Place the free official 2026 IAASB Handbook PDF in local_pdfs/ and run `python3 scripts/import_private_intl_pdfs.py`.","seq":2}]});
